import{_ as r,K as l,a as n,c as d,ac as e,b as i,q as o}from"./chunks/framework.BSuaGltH.js";const f=JSON.parse('{"title":"羽毛球规则 · 适用范围与规则版本至违例、擦网与重发","description":"以 BWF 21 分制规则讲解单打和双打的场地边线、发球站位、轮转、违例、重发与常见判例。","frontmatter":{"title":"羽毛球规则 · 适用范围与规则版本至违例、擦网与重发","description":"以 BWF 21 分制规则讲解单打和双打的场地边线、发球站位、轮转、违例、重发与常见判例。","splitFrom":"life/personal/sports/badminton-rules.md","showdocs":{"topics":[{"id":"personal","title":"生活记录","link":"/topics/personal/"}],"kind":"基础学习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"羽毛球规则","summary":"以 BWF 21 分制规则讲解单打和双打的场地边线、发球站位、轮转、违例、重发与常见判例。","status":"active","related":[{"title":"第七号嫌疑人","link":"/life/personal/reading-games/suspect-number-seven","kind":"生活记录","scope":"general","audience":"general"},{"title":"佳能入门","link":"/life/personal/photography/canon","kind":"生活记录","scope":"general","audience":"general"},{"title":"《十翼》逐篇阅读：七种十篇怎样帮助理解《周易》","link":"/life/personal/yijing/ten-wings","kind":"基础学习","scope":"general","audience":"general"},{"title":"《算法》书目与主题导读（版本待确认）","link":"/life/personal/books/computing/algorithms","kind":"书籍导读","scope":"general","audience":"general"},{"title":"《周易》是怎样的一部书：经、传、注与成书问题","link":"/life/personal/yijing/text-history","kind":"基础学习","scope":"general","audience":"general"}],"prev":{"text":"羽毛球规则","link":"/life/personal/sports/badminton-rules"},"next":{"text":"羽毛球规则 · 从挑边到结束：新手比赛顺序至官方来源与查阅方法","link":"/life/personal/sports/badminton-rules-part-02"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"羽毛球规则","link":"/life/personal/sports/badminton-rules"},"next":{"text":"羽毛球规则 · 从挑边到结束：新手比赛顺序至官方来源与查阅方法","link":"/life/personal/sports/badminton-rules-part-02"}},"headers":[],"relativePath":"life/personal/sports/badminton-rules-part-01.md","filePath":"life/personal/sports/badminton-rules-part-01.md"}'),s={name:"life/personal/sports/badminton-rules-part-01.md"};function p(h,t,c,u,b,g){const a=l("ArticleImage");return n(),d("div",null,[t[0]||(t[0]=e('<h1 id="羽毛球规则-·-适用范围与规则版本至违例、擦网与重发" tabindex="-1">羽毛球规则 · 适用范围与规则版本至违例、擦网与重发 <a class="header-anchor" href="#羽毛球规则-·-适用范围与规则版本至违例、擦网与重发" aria-label="Permalink to &quot;羽毛球规则 · 适用范围与规则版本至违例、擦网与重发&quot;">​</a></h1><p><a href="/life/personal/sports/badminton-rules">返回分篇目录</a></p><p>羽毛球每个回合都争夺一分。理解规则的关键是把“发球时的有效区域”和“相持时的有效区域”分开，再用发球方的得分判断左右发球区。</p><h2 id="羽毛球规则" tabindex="-1">羽毛球规则 <a class="header-anchor" href="#羽毛球规则" aria-label="Permalink to &quot;羽毛球规则 {#羽毛球规则}&quot;">​</a></h2><p>羽毛球每个回合都争夺一分。理解规则的关键是把“发球时的有效区域”和“相持时的有效区域”分开，再用发球方的得分判断左右发球区。</p><h2 id="适用范围与规则版本" tabindex="-1">适用范围与规则版本 <a class="header-anchor" href="#适用范围与规则版本" aria-label="Permalink to &quot;适用范围与规则版本 {#适用范围与规则版本}&quot;">​</a></h2><p>本文固定以 <strong>BWF《Laws of Badminton》2025 年版本的三局两胜、每局 21 分制</strong> 为学习口径，涵盖常规单打、双打和混双，不展开残疾人羽毛球特殊规定。</p><p><strong>21 分制与 15 分制不能混用。</strong> 新计分制的试行、表决通过和正式生效是不同节点；比赛如果采用 15 分制，需要连同加分上限、局中休息、决胜局换边节点一起查对应规程。本文中的 21、30、11 分均属于本节指定的 21 分制，不把未来生效的修改提前套入本版本。</p><h2 id="人数、场地与边线" tabindex="-1">人数、场地与边线 <a class="header-anchor" href="#人数、场地与边线" aria-label="Permalink to &quot;人数、场地与边线 {#人数、场地与边线}&quot;">​</a></h2><p>单打每方 1 人，双打和混双每方 2 人。场地长 13.40 米，双打宽 6.10 米，单打宽 5.18 米；线宽 40 毫米。网柱处网高 1.55 米，中央网高 1.524 米。</p><p><strong>界线属于它所界定的区域，压线算界内。</strong> 羽毛球落点主要看球托首先接触地面的位置，不用羽毛向外伸出的范围判断出界。</p><table tabindex="0"><thead><tr><th>情况</th><th>左右边界</th><th>前后边界</th></tr></thead><tbody><tr><td>单打发球</td><td>单打内侧边线与中线之间</td><td>短发球线至最外侧底线</td></tr><tr><td>双打发球</td><td>双打外侧边线与中线之间</td><td>短发球线至双打后发球线</td></tr><tr><td>单打相持</td><td>单打内侧边线</td><td>最外侧底线</td></tr><tr><td>双打相持</td><td>双打外侧边线</td><td>最外侧底线</td></tr></tbody></table><p>短发球线距球网 1.98 米；双打后发球线在最外侧底线内 0.76 米处。记忆为：<strong>单打发球窄而长，双打发球宽而短；双打接发完成后的相持可以打到底线。</strong> 两种发球都必须斜线进入对角发球区。</p><h2 id="看图选对边线" tabindex="-1">看图选对边线 <a class="header-anchor" href="#看图选对边线" aria-label="Permalink to &quot;看图选对边线 {#看图选对边线}&quot;">​</a></h2>',14)),i("p",null,[o(a,{src:"/images/sports/badminton-court.svg",alt:"羽毛球场比例图：单双打边线及发球后界不同"})]),t[1]||(t[1]=e('<p><em>图：按 13.40 × 6.10 米绘制，两条内侧长线之间是单打宽度 5.18 米。底部以本方右区为例：① 是最外底线前的后条带，② 是外侧边道的一段。发球必须进入对角有效区；此图着重比较区域，不表示球可以直线发往图中标记。</em></p><p>拿同一个落点分别问三遍：<strong>单打还是双打？发球还是相持？球托落在什么位置？</strong> ① 在单打发球时有效，在双打发球时过长；② 在双打发球时有效，在单打时过宽。相持开始后，双打这两处都有效。短发球线只限制发球落点，相持中可以把球轻放在网与短发球线之间。</p><h2 id="计分、换边与间歇" tabindex="-1">计分、换边与间歇 <a class="header-anchor" href="#计分、换边与间歇" aria-label="Permalink to &quot;计分、换边与间歇 {#计分、换边与间歇}&quot;">​</a></h2><p>三局两胜，每个回合获胜一方得 1 分。一般先到 21 分者赢一局，但有两个加分条件：</p><ul><li>20∶20 后，必须领先 2 分，例如 22∶20、25∶23。</li><li>到 29∶29 时，谁先拿到第 30 分谁赢，因此 30∶29 可以结束一局。</li></ul><p>上一局胜方在下一局先发球。第一局结束交换场地；如果需要第三局，第二局结束后交换；第三局有一方先到 <strong>11 分</strong> 时再交换。发现忘记换边，应在球不处于比赛状态时立即纠正，已有比分不变。</p><p>每局领先一方达到 11 分时，可有不超过 60 秒的间歇；局与局之间可有不超过 120 秒的间歇。常规规则没有供球员随时申请的“每局一次战术暂停”，不能用擦汗、喝水等方式自行中断连续比赛。</p><h2 id="开赛与合法发球" tabindex="-1">开赛与合法发球 <a class="header-anchor" href="#开赛与合法发球" aria-label="Permalink to &quot;开赛与合法发球 {#开赛与合法发球}&quot;">​</a></h2><p>赛前挑边胜方可选择先发或先接，或者选择场地；另一方选择剩余选项。每局报分时先报发球方得分，再报接发球方得分。</p><p>发球不是只要把球打进斜对角就合法。根据 BWF 第 9 条，发球员和接发球员还须满足以下条件：</p><ol><li>站在斜对角发球区内，脚不能踩发球区边界线。</li><li>从发球开始到发出，双方两脚都应有一部分保持接触地面并处于静止状态；不能起跳发球或提前移动接发。</li><li>击球瞬间，<strong>整个球必须低于距地面 1.15 米</strong>，不是只要求球托低于，也不是用某个人的腰部高度替代。</li><li>球拍首先击中球托；释放球时不得人为给球加旋转后再击打，也就是不能使用被禁止的旋转发球。</li><li>发球动作开始后，球拍向前的运动应连续，不能假动作前挥后停住再发。发球员挥拍尝试发球却没有击中，也算发球失误。</li><li>球应向上越网；若不被接发球员截击，应落入对角的正确发球区内。</li></ol><p>接发球员准备好之前不应发球；但接发球员已经尝试回接，就视为准备好。双方准备好后也不能故意拖延。球友约定采用旧的“不过腰”办法时，应知道这与本页的固定高度规则并不相同。</p><h2 id="单打-偶数右区、奇数左区" tabindex="-1">单打：偶数右区、奇数左区 <a class="header-anchor" href="#单打-偶数右区、奇数左区" aria-label="Permalink to &quot;单打：偶数右区、奇数左区 {#单打-偶数右区、奇数左区}&quot;">​</a></h2><p>用 <strong>发球员自己的得分</strong> 决定站位：0 分或偶数分从右发球区发，奇数分从左发球区发，对方站在斜对角区域接发。</p><p>发球方赢球，得 1 分并继续发球，同时换到另一侧发球区；接发球方赢球，得 1 分并获得发球权，按自己的新得分选择左右区。</p><p>例如甲以 6∶5 领先并发球，甲从右区发；甲赢后比分为 7∶5，改从左区发。如果乙赢，乙的新得分是 6，接着由乙从右区发，报分为 6∶6。不要用总分的奇偶或接发球员的分数判断发球区。</p><h2 id="双打-谁发、谁接、何时换位" tabindex="-1">双打：谁发、谁接、何时换位 <a class="header-anchor" href="#双打-谁发、谁接、何时换位" aria-label="Permalink to &quot;双打：谁发、谁接、何时换位 {#双打-谁发、谁接、何时换位}&quot;">​</a></h2><p>双打同样遵守“发球方偶数右、奇数左”，但要同时记住两名队员在左右发球区的位置关系。每次丢掉发球权，就由对方发球，<strong>没有旧制中一方两个人依次发球的第二发球权</strong>。</p><ul><li>本方正在发球且赢了这一分：原发球员继续发，队友与其交换左右发球区。</li><li>本方正在发球但输掉这一分：本方不交换发球区，由对方按新得分确定发球员。</li><li>本方正在接发球且赢了这一分：获得发球权，本方不因这次得分交换发球区；站在与新得分奇偶对应区域的人发球。</li><li>只有站在发球员斜对角的指定接发球员可以回接发球，接发同伴抢接会违例。</li></ul><h3 id="四个回合看懂轮转" tabindex="-1">四个回合看懂轮转 <a class="header-anchor" href="#四个回合看懂轮转" aria-label="Permalink to &quot;四个回合看懂轮转 {#四个回合看懂轮转}&quot;">​</a></h3><p>设甲乙一队、丙丁一队。0∶0 时，甲在右区发给右区的丙，乙和丁各在左区。表中比分一直按“甲乙队∶丙丁队”记录。</p><table tabindex="0"><thead><tr><th>回合结果</th><th>新比分</th><th>下一次发球</th></tr></thead><tbody><tr><td>甲乙赢第一分</td><td>1∶0</td><td>甲换到左区，发给丁</td></tr><tr><td>丙丁赢下一分</td><td>1∶1</td><td>丁原在左区，由丁发给甲</td></tr><tr><td>丙丁再赢一分</td><td>1∶2</td><td>丁换到右区，发给乙</td></tr><tr><td>甲乙赢下一分</td><td>2∶2</td><td>乙原在右区，由乙发给丁</td></tr></tbody></table><p>表中的左右是球员面向球网时自己的左右。相持开始后，两名队员可以自由跑动、采用前后或左右站位，也可以由同一人连续接本方不同回合的来球；<strong>不要求像乒乓球双打那样每拍轮流打</strong>。发球区的位置关系用于确定下一球谁发、谁接，不是禁止相持换位。</p><p>若发现发接球次序或区域错误，在球不处于比赛状态时纠正，已经取得的比分保留。</p><h2 id="违例、擦网与重发" tabindex="-1">违例、擦网与重发 <a class="header-anchor" href="#违例、擦网与重发" aria-label="Permalink to &quot;违例、擦网与重发 {#违例、擦网与重发}&quot;">​</a></h2><p>下列情形通常由违例方丢掉一分：球落在有效区外、未过网、触到天花板或墙壁、触到运动员身体或衣服、被球拍夹住后拖带抛出、同一方两名队员连续击同一个来球，以及球处于比赛状态时球拍、身体或衣服触网。</p><p>同一名球员连续击球通常违例，但一个连续击球动作中，球先碰拍框再碰拍弦，不按两次击球判罚。不能据此允许两次独立挥拍“补救”。</p><h3 id="网前的三个边界" tabindex="-1">网前的三个边界 <a class="header-anchor" href="#网前的三个边界" aria-label="Permalink to &quot;网前的三个边界 {#网前的三个边界}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>场景</th><th>判断</th></tr></thead><tbody><tr><td>发球擦网后仍落进正确的对角发球区</td><td>合法，继续比赛；羽毛球没有“发球擦网一律重发”</td></tr><tr><td>相持擦网后过网落在对方界内</td><td>合法</td></tr><tr><td>在本方一侧先击中球，随挥球拍越过球网</td><td>可以，前提是不触网、不妨碍对方</td></tr><tr><td>球尚在对方一侧，就把球拍伸过去抢击</td><td>违例</td></tr><tr><td>身体或球拍从网下侵入对方场区</td><td>若造成妨碍或分散对方注意力，则违例</td></tr></tbody></table><p>重发通常适用于发球员在接发球员尚未准备好时发球、双方同时在发球中违例、球破损到球托和羽毛完全分离，或裁判无法作出有效判定等情况。重发后该回合不计分，由原发球员再次发球。</p><p>球挂在网顶或过网后挂住网的处理还与发生阶段有关：发球时属于违例；接发球已经被回击以后出现规则规定的挂网情况，可判重发。不要把所有“碰到网的异常球”都视为同一种情况。</p>',31))])}const _=r(s,[["render",p]]);export{f as __pageData,_ as default};
